<script setup lang="ts">import{ref}from'vue';import{read,utils}from'xlsx';import{parseJobRows,type JobImportPreview}from'./parseJobRows';const preview=ref<JobImportPreview|null>(null);const importing=ref(false);const fileError=ref('');const sample=[['公司名称','职位名称','城市','投递链接','截止时间'],['星海科技','Java 后端工程师','上海','https://example.com/apply/1','2026-10-20'],['云帆智能','产品经理','杭州','https://example.com/apply/2','2026-10-28'],['','数据分析师','北京','bad-url','2026/11/01']];async function choose(event:Event){fileError.value='';const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.xlsx')){fileError.value='请选择 .xlsx 文件';return}if(file.size>5*1024*1024){fileError.value='文件不能超过 5MB';return}try{const workbook=read(await file.arrayBuffer(),{type:'array',raw:false});const name=workbook.SheetNames[0];if(!name)throw new Error('工作簿没有工作表');const sheet=workbook.Sheets[name];if(!sheet)throw new Error('无法读取第一个工作表');const rows=utils.sheet_to_json<unknown[]>(sheet,{header:1,raw:false,defval:''});if(rows.length>2001)throw new Error('数据不能超过 2,000 行');preview.value=parseJobRows(rows)}catch(value){fileError.value=value instanceof Error?value.message:'文件解析失败，请检查模板格式'}}function loadSample(){fileError.value='';preview.value=parseJobRows(sample)}async function confirmImport(){if(!preview.value?.validRows.length)return;importing.value=true;await new Promise(resolve=>setTimeout(resolve,600));importing.value=false;window.alert(`已模拟导入 ${preview.value.validRows.length} 条有效职位`)}</script>
<template><section><header class="admin-page-head"><div><h1>导入职位</h1><p>上传 Excel 后先校验预览，确认无误再写入职位库。</p></div><button class="cl-quiet-button" @click="loadSample">载入演示文件</button></header><label class="upload cl-card"><strong>选择 Excel 文件</strong><span>支持 .xlsx，最大 5MB、2,000 行；模板列为公司名称、职位名称、城市、投递链接、截止时间。</span><input type="file" accept=".xlsx" @change="choose"/><em v-if="fileError" role="alert">{{fileError}}</em></label><template v-if="preview"><div class="import-summary"><span><b>{{preview.validRows.length}}</b> 有效</span><span><b>{{preview.warningRows.length}}</b> 警告</span><span class="danger"><b>{{preview.invalidRows.length}}</b> 错误</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>行号</th><th>公司</th><th>职位</th><th>城市</th><th>截止时间</th><th>校验结果</th></tr></thead><tbody><tr v-for="item in [...preview.validRows,...preview.invalidRows]" :key="item.rowNumber"><td>{{item.rowNumber}}</td><td>{{item.companyName||'—'}}</td><td>{{item.jobTitle}}</td><td>{{item.city}}</td><td>{{item.deadline}}</td><td :class="{danger:item.errors.length}">{{item.errors.length?item.errors.map(error=>error.message).join('；'):'通过'}}</td></tr></tbody></table></div><footer class="import-actions"><button class="cl-quiet-button">下载错误报告</button><button class="cl-primary-button" :disabled="!preview.validRows.length||importing" @click="confirmImport">{{importing?'正在导入…':`导入 ${preview.validRows.length} 条有效职位`}}</button></footer></template></section></template>
<style scoped>.upload{display:grid;gap:8px;padding:28px;border-style:dashed;text-align:center}.upload span{color:var(--cl-muted)}.upload input{margin:auto}.upload em{color:var(--cl-danger);font-style:normal}.import-summary{display:flex;gap:30px;margin:22px 0}.import-summary b{font-size:24px}.danger{color:var(--cl-danger)}.import-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:16px}</style>
